package com.bank.raisepolicy;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class RaisePolicyDemo {
    private static final Logger log = Logger.getLogger("RaisePolicy");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", new BigDecimal("1000000")),
            new Employee("Priya", "Sales", new BigDecimal("200000")),
            new Employee("Amit", "Risk", new BigDecimal("500000")));   // other → 5%
        RaisePolicyService service = new RaisePolicyService();

        service.applyPolicy(staff).forEach(e ->
            log.info(() -> e.getName() + " (" + e.getDepartment() + ") → " + e.getSalary()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final BigDecimal salary;
    Employee(String name, String department, BigDecimal salary) {
        this.name = name; this.department = department; this.salary = salary;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    BigDecimal getSalary() { return salary; }
}

// ─── Would be in service/RaisePolicyService.java ───
class RaisePolicyService {
    // policy as DATA: department → raise %
    private static final Map<String, BigDecimal> POLICY = Map.of(
        "IT", new BigDecimal("10"),
        "Sales", new BigDecimal("15"));
    private static final BigDecimal DEFAULT_PCT = new BigDecimal("5");

    List<Employee> applyPolicy(List<Employee> staff) {
        return staff.stream()
            .map(e -> {
                BigDecimal pct = POLICY.getOrDefault(e.getDepartment(), DEFAULT_PCT); // lookup+default
                BigDecimal factor = BigDecimal.ONE.add(pct.movePointLeft(2));         // 1 + pct/100
                BigDecimal newSalary = e.getSalary().multiply(factor)
                    .setScale(2, java.math.RoundingMode.HALF_UP);                     // exact money
                return new Employee(e.getName(), e.getDepartment(), newSalary);        // new object
            })
            .toList();
    }
}
